(()=>{const list=document.getElementById('notice-list'),empty='<article class="notice-empty"><h2>등록된 공지사항이 없습니다</h2><p>새 안내가 등록되면 이곳에서 확인할 수 있습니다.</p></article>';function date(item){const value=item.createdAt;const raw=value?.toDate?value.toDate():value?.seconds?new Date(value.seconds*1000):new Date();return raw.toLocaleDateString('ko-KR')}function render(items=[]){const sorted=[...items].sort((a,b)=>Number(b.pinned)-Number(a.pinned)||(b.createdAt?.seconds||0)-(a.createdAt?.seconds||0));list.innerHTML=sorted.length?sorted.map(item=>`<article class="notice-row"><span>${item.pinned?'고정':item.type}</span><div><h2>${escapeHTML(item.title)}</h2><p>${escapeHTML(item.content)}</p></div><time>${date(item)}</time></article>`).join(''):empty}function escapeHTML(value){return String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]))}window.addEventListener('moodnote-notices',event=>render(event.detail.notices));render()})();
